import{_ as r,l as s,o as e,c as l,v as t,p as n,x as o,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"抽象数据类型","description":"","frontmatter":{"title":"抽象数据类型","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/adt-cost.md","filePath":"cs/adt-cost.md","lastUpdated":1789023840000}'),A={name:"cs/adt-cost.md"};function h(E,a,m,_,B,T){const i=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="抽象数据类型" tabindex="-1">抽象数据类型 <a class="header-anchor" href="#抽象数据类型" aria-label="Permalink to &quot;抽象数据类型&quot;">​</a></h1><div class="epigraph"><p>先约定对象上允许哪些操作以及它们的代价，再选一种比特布局去实现；布局可换，合同不能偷换。</p><footer>—— 据 Liskov and Zilles, Programming with Abstract Data Types, SIGPLAN 1974；Cormen, Leiserson, Rivest and Stein, Introduction to Algorithms 整理</footer></div><p><a href="/cs/dram-timing">上一课</a>把指令、cache、一致性和远程内存都收进可执行的机器：比特已经能算、能存、能在核间可见。本课不重讲 MESI，也不从「计算机是什么」另起。缺口是：还没有给<strong>可复用的布局</strong>命名——栈、表、图在 ISA 里都只是 load/store。<a href="/cs/bit-as-distinction">比特作为区分</a>给出串，<a href="/cs/asymptotic-notation">渐近记号</a>给出步数怎么写。本课只钉抽象数据类型：操作集合加代价，实现另选。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>体系结构课结束时，程序员仍每次用手排寄存器和地址。同一套「后进先出」可以是数组顶指针，也可以是链表，调用约定已经用过其中一种，却没有把它写成可替换的合同。缺口不是新的特权级，而是把对象从具体指令里抽出来：<strong>构造、插入、查找、删除各允许做什么，最坏或摊还各多少步</strong>。</p><p>没有这层，后课无法比较数组与链表：它们会混成「都是一串元素」。代价必须进合同，否则局部性与 \\(O(1)\\) 下标会被说成同一件事。</p><p><span class="marginnote">ADT 不是 OOP 课。Liskov 强调的是接口与表示分离；本栏用它连接 ISA 与 CLRS 里的结构。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>指定一个对象类型 \\(T\\) 和有限个操作，每个操作给出前置条件与渐近代价（最坏、平均或摊还，须声明）。正确性相对抽象状态（序列、集合、全序映射），不相对某次 <code>sw</code> 的地址。同一 \\(T\\) 可以有多种表示，后课逐个给。</p>',9)),(e(),n(p,null,{default:o(()=>[c(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ISA%5B%22%E6%8C%87%E4%BB%A4%E5%B7%B2%E8%83%BD%E6%89%A7%E8%A1%8C%22%5D%20--%3E%20ADT%5B%22%E6%93%8D%E4%BD%9C%20%2B%20%E4%BB%A3%E4%BB%B7%E5%90%88%E5%90%8C%22%5D%0A%20%20ADT%20--%3E%20ARR%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%95%B0%E7%BB%84%E8%A1%A8%E7%A4%BA%22%5D%0A%20%20ADT%20--%3E%20LIST%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E9%93%BE%E8%A1%A8%E8%A1%A8%E7%A4%BA%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>本课不引入任何一种具体结构的不变式细节。只要求：换表示不得偷偷改合同——若查找从 \\(O(1)\\) 变成 \\(O(n)\\)，那是另一种 ADT 或另一种实现承诺。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有了合同，<a href="/cs/locality-principle">局部性原理</a>变成实现层的注释：同一「取第 \\(i\\) 个」在数组上吃空间局部性，在链表上可能每次 cache 缺失。渐近记号数的是步，步的常数含命中与缺失；后课会把两者拆开写，但合同先写步数。</p><p>NUMA 上远程节点是又一层常数。ADT 课默认分析单处理器 RAM 模型，需要时再加一句「布局破坏局部性则常数爆炸」，不把每课重写成体系结构。后课的每一种结构，都先写合同再写一种表示，不从晶体管另起。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把类、继承、虚函数请进来。也不把「抽象」写成无代价：没有代价的接口无法在后课做选择。形式化代数规范（ADT 作为等式理论）不在主干。</p><p>后课默认：谈到栈、队列、字典、图，先有操作与代价，再谈表示。第一份表示是数组。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>机器会执行了；本课开始命名操作合同，而不是某次 load 的地址。</li><li>ADT = 操作 + 代价；表示可换，合同不可偷。</li><li>数组随机访问是下一课的第一种表示。</li><li>本课不把类与继承请进来；没有代价的接口无法选择表示。</li><li>出处：Liskov and Zilles, 1974；Cormen et al., <em>Introduction to Algorithms</em>。</li></ul>',9))])}const D=r(A,[["render",h]]);export{f as __pageData,D as default};
